before.match.go:
package app
// match compares ASCII strings ignoring case.
func match(a,b string) bool { return a==b }

after.match.go:
package app
import "strings"
// match compares ASCII strings ignoring case.
func match(a,b string) bool { return normalize(a)==normalize(b) }
func normalize(s string) string { return strings.ToLower(s) }

