before.join.go:
package app
// join concatenates all strings without a separator.
func join(xs []string) string { s:=""; for _,x:=range xs { s+=x }; return s }

after.join.go:
package app
import "strings"
// join concatenates all strings without a separator.
// Avoid repeated allocations and copying of the accumulated prefix.
func join(xs []string) string { return strings.Join(xs,"") }

